/* Lab Arcade, wave 2: deeper coverage for chemistry, law, religion, literature, ethics, anthropology, linguistics, geopolitics, logic and sociology */
(function () {
  const A = Lab.ARC.add, h = Lab.h;
  const bars = (rows, max, fmt = (v) => Lab.fmt(v, 1)) => h('div', null, rows.map(([l, v, c]) => h('div', { class: 'row', style: { margin: '4px 0', flexWrap: 'nowrap' } }, h('span', { class: 'small', style: { width: '200px', flex: 'none' } }, l), h('div', { style: { flex: 1, height: '18px', background: 'var(--card2)', borderRadius: '6px' } }, h('div', { style: { width: Math.max(0.5, Math.min(100, (v / max) * 100)) + '%', height: '100%', background: c || '#2563EB', borderRadius: '6px' } })), h('b', { class: 'small', style: { width: '100px', flex: 'none', textAlign: 'right' } }, fmt(v)))));
  const cards = (K, el, items) => items.forEach(([t, d, opts, ans]) => { const fb = h('div', { class: 'small', style: { marginTop: '6px' } }); el.append(h('div', { class: 'card', style: { boxShadow: 'none', marginBottom: '10px' } }, h('b', null, t), h('p', { class: 'small' }, d), h('div', { class: 'row' }, opts.map((o) => K.btn(o, () => { fb.innerHTML = `<b>You chose:</b> ${o}. ${ans}`; }))), fb)); });

  // Honest cross-tags for labs that genuinely belong to more fields
  const tag = (id, ...ds) => { const L = Lab.ARC.by[id]; if (L) ds.forEach((d) => !L.d.includes(d) && L.d.push(d)); };
  tag('commons', 'sociology', 'ethics'); tag('publicgoods', 'anthropology', 'ethics'); tag('ultimatum', 'ethics'); tag('gametheory', 'sociology', 'ethics'); tag('spurious', 'sociology'); tag('telephone', 'literature'); tag('readability', 'law'); tag('fallacies', 'law'); tag('condorcet', 'philosophy'); tag('pascal', 'logic'); tag('simpson', 'ethics'); tag('chokepoints', 'politics'); tag('climate', 'ethics'); tag('resistance', 'ethics'); tag('sir', 'ethics'); tag('lorenz', 'ethics'); tag('outofafrica', 'geopolitics');

  // ======================= CHEMISTRY =======================
  A({ id: 'molarmass', d: ['chemistry', 'biology', 'medicine'], e: '⚖️', t: 'Molar mass & composition', b: 'Type any chemical formula and see its mass and what share of it each element makes up.',
    how: 'Each element’s atomic mass (in g/mol) comes from the periodic table. Add them up by count to get the molar mass: one mole (6.022 × 10²³ molecules, Avogadro’s number) weighs that many grams. Mass percentages explain, for example, why most of your body’s mass is oxygen (it’s in water).',
    use: 'Drug dosing, nutrition labels, fertilizer and fuel calculations, lab work and industrial chemistry.',
    m(el, K) {
      const M = { H: 1.008, He: 4.003, C: 12.011, N: 14.007, O: 15.999, F: 18.998, Na: 22.99, Mg: 24.305, Al: 26.982, Si: 28.086, P: 30.974, S: 32.06, Cl: 35.45, K: 39.098, Ca: 40.078, Fe: 55.845, Cu: 63.546, Zn: 65.38, Br: 79.904, Ag: 107.87, I: 126.9, Au: 196.97, U: 238.03 };
      const inp = h('input', { type: 'text', value: 'C6H12O6', style: { width: '200px', fontFamily: 'monospace', fontSize: '18px' } }); const out = h('div');
      const parse = (s) => { const st = [{}]; const re = /([A-Z][a-z]?|\(|\)|\d+)/g; let m, last = null; const toks = s.match(re) || []; for (let i = 0; i < toks.length; i++) { const t = toks[i]; const n = /^\d+$/.test(toks[i + 1] || '') ? +toks[++i] : 1; if (t === '(') { st.push({}); i -= n === 1 ? 0 : 1; continue; } if (t === ')') { const g = st.pop(); for (const k in g) st[st.length - 1][k] = (st[st.length - 1][k] || 0) + g[k] * n; continue; } if (!M[t]) throw new Error(t); st[st.length - 1][t] = (st[st.length - 1][t] || 0) + n; } return st[0]; };
      const run = () => { try { const c = parse(inp.value.trim()); const tot = Object.entries(c).reduce((a, [e, n]) => a + M[e] * n, 0); out.innerHTML = `<div class="kpi">${tot.toFixed(3)} g/mol</div>`; out.append(bars(Object.entries(c).map(([e, n], i) => [`${e} × ${n}`, (M[e] * n / tot) * 100, K.pal[i % 8]]), 100, (v) => v.toFixed(1) + '%')); } catch (e) { out.textContent = 'Unknown element or formula. Use capital letters, e.g. Ca(OH)2.'; } };
      inp.oninput = run; el.append(h('div', { class: 'row' }, inp, ...[['Glucose', 'C6H12O6'], ['Water', 'H2O'], ['Caffeine', 'C8H10N4O2'], ['Aspirin', 'C9H8O4'], ['Table salt', 'NaCl'], ['Limestone', 'CaCO3'], ['Ammonium nitrate', 'NH4NO3']].map(([n, f]) => K.btn(n, () => { inp.value = f; run(); }))), out); run();
    } });

  A({ id: 'bondtype', d: ['chemistry', 'physics'], e: '🔗', t: 'Ionic, polar or covalent?', b: 'Pick two elements. The difference in how hard they pull electrons decides the bond.',
    how: 'Linus Pauling (1932) defined electronegativity: how strongly an atom attracts shared electrons. A large difference (above about 1.7–2.0) means one atom takes the electron: an ionic bond (NaCl). A moderate difference gives a polar covalent bond (water’s O–H); a small one a nonpolar bond (H–H, C–H).',
    use: 'Why salt dissolves in water but oil doesn’t, how soap works, protein folding, drug design and materials science.',
    m(el, K) {
      const EN = { H: 2.2, Li: 0.98, C: 2.55, N: 3.04, O: 3.44, F: 3.98, Na: 0.93, Mg: 1.31, Al: 1.61, Si: 1.9, P: 2.19, S: 2.58, Cl: 3.16, K: 0.82, Ca: 1.0, Br: 2.96, I: 2.66, Cs: 0.79 }; let a = 'Na', b = 'Cl'; const out = h('div'); const P = K.canvas(el, 120);
      const draw = () => { const d = Math.abs(EN[a] - EN[b]); const type = d >= 1.8 ? ['Ionic', '#DC2626', 'One atom essentially takes the electron.'] : d >= 0.5 ? ['Polar covalent', '#CA8A04', 'Electrons are shared unequally: one end is slightly negative.'] : ['Nonpolar covalent', '#16A34A', 'Electrons are shared almost equally.']; P.clear(); const { X } = P.chart(0, 3.3, 0, 1, { noY: true, xl: 'electronegativity difference' }); [[0, 0.5, '#16A34A'], [0.5, 1.8, '#CA8A04'], [1.8, 3.3, '#DC2626']].forEach(([x0, x1, c]) => P.rect(X(x0), 20, X(x1) - X(x0), 50, c + '44')); P.line([[X(d), 10], [X(d), 80]], '#111', 3);
        out.innerHTML = `${a} (${EN[a]}) – ${b} (${EN[b]}): difference <b>${d.toFixed(2)}</b> → <b style="color:${type[1]}">${type[0]}</b>. ${type[2]}`; };
      P.onResize = draw; const sel = (v, on) => { const s = h('select', null, Object.keys(EN).map((k) => h('option', { value: k, selected: k === v }, k))); s.onchange = () => on(s.value); return s; };
      el.append(h('div', { class: 'row' }, sel(a, (v) => { a = v; draw(); }), h('span', null, '+'), sel(b, (v) => { b = v; draw(); }), ...[['Na', 'Cl'], ['H', 'O'], ['C', 'H'], ['H', 'H'], ['C', 'O'], ['Cs', 'F']].map(([x, y]) => K.btn(x + '–' + y, () => { a = x; b = y; draw(); }))), out); draw();
    } });

  A({ id: 'fuels', d: ['chemistry', 'engineering', 'earthspace', 'economics'], e: '⛽', t: 'Energy in a kilogram', b: 'Gasoline, batteries, food, hydrogen, uranium. Compare how much energy each stores, on a log scale.',
    how: 'Chemical fuels release energy when bonds rearrange (combustion); batteries move electrons between electrodes; nuclear fission converts a tiny amount of mass into energy (E = mc²), millions of times more per kilogram. Energy density shapes which technologies are practical: why planes still burn kerosene and why EV batteries are heavy.',
    use: 'Electric cars, aviation, climate policy, nutrition (fat stores about twice the energy of sugar), and nuclear power debates.',
    m(el, K) {
      const F = [['Uranium-235 (fission, theoretical)', 8.0e7, '#9333EA'], ['Hydrogen', 120, '#0EA5E9'], ['Natural gas', 53.6, '#2563EB'], ['Gasoline', 46.4, '#DC2626'], ['Diesel', 45.6, '#B91C1C'], ['Body fat', 37, '#CA8A04'], ['Coal', 24, '#334155'], ['Sugar / carbohydrate', 17, '#EA580C'], ['Dry wood', 16, '#92400E'], ['TNT', 4.6, '#DB2777'], ['Lithium-ion battery', 0.9, '#16A34A'], ['Lead-acid battery', 0.15, '#64748B']]; let log = true; const box = h('div');
      const draw = () => { box.innerHTML = ''; box.append(bars(F.map(([n, v, c]) => [n, log ? Math.log10(v) + 1 : Math.min(v, 130), c]), log ? 9 : 130, (v) => (log ? Lab.fmt(10 ** (v - 1), 1) : Lab.fmt(v, 1)) + ' MJ/kg')); };
      el.append(K.choice([[true, 'Log scale (see everything)'], [false, 'Linear (uranium off the chart)']], true, (v) => { log = v; draw(); }), box, h('p', { class: 'tiny muted' }, 'Approximate lower heating values. Batteries look poor per kg, but electric motors are about 3× more efficient than combustion engines at turning stored energy into motion.')); draw();
    } });

  A({ id: 'buffer', d: ['chemistry', 'medicine', 'biology', 'earthspace'], e: '🩸', t: 'Buffers: how blood resists acid', b: 'Add acid drop by drop to plain water and to a buffer. One barely budges.',
    how: 'A buffer is a weak acid plus its partner base; it soaks up added acid or base. Blood uses the carbonic acid–bicarbonate buffer to stay at pH 7.35–7.45. The Henderson–Hasselbalch equation, pH = pKa + log([base]/[acid]), predicts it. Oceans are buffered too, but absorbing CO₂ is slowly using up that capacity.',
    use: 'Medicine (acidosis in kidney disease or diabetes), shampoos and foods, lab work, swimming pools and ocean acidification.',
    m(el, K) {
      const P = K.canvas(el, 260); let added = 0, conc = 0.1; const out = K.out();
      const draw = () => { P.clear(); const { X, Y } = P.chart(0, 20, 0, 14, { xl: 'mL of strong acid added', yl: 'pH' }); const water = [], buf = []; for (let v = 0; v <= 20; v += 0.1) { const H = (v * 0.1) / (100 + v); water.push([X(v), Y(v === 0 ? 7 : Math.max(0, -Math.log10(H)))]); const A0 = conc * 100, HA0 = conc * 100, add = v * 0.1; const pH = add < A0 ? 6.1 + Math.log10((A0 - add) / (HA0 + add)) : Math.max(0, -Math.log10((add - A0) / (100 + v) + 1e-9)); buf.push([X(v), Y(pH + 1.3)]); }
        P.line(water, '#DC2626', 2.5); P.line(buf, '#2563EB', 2.5); P.line([[X(added), Y(0)], [X(added), Y(14)]], K.css('--muted'), 1, [4, 4]); out.innerHTML = '<span style="color:#DC2626">Plain water</span> crashes from pH 7 with the first drops. <span style="color:#2563EB">Buffered solution</span> (bicarbonate-style, shifted to start near 7.4) holds steady until its capacity runs out.'; };
      P.onResize = draw; el.append(K.slider('Acid added (mL)', 0, 20, 0.1, added, (v) => { added = v; draw(); }), K.slider('Buffer strength', 0.02, 0.3, 0.01, conc, (v) => { conc = v; draw(); }), out); draw();
    } });

  A({ id: 'haber', d: ['chemistry', 'history', 'economics', 'earthspace'], e: '🌾', t: 'The Haber process trade-off', b: 'Make ammonia fertilizer from air. High temperature is fast but yields less; high pressure yields more but costs more.',
    how: 'N₂ + 3H₂ ⇌ 2NH₃ releases heat, so by Le Chatelier’s principle low temperature favors ammonia, but the reaction is then too slow. Fewer gas molecules on the right means high pressure helps. Industry compromises at about 400–450 °C and 150–250 atmospheres with an iron catalyst. Fritz Haber (Nobel 1918) also led Germany’s WWI chemical weapons program.',
    use: 'Synthetic fertilizer feeds an estimated half of humanity; the process uses about 1–2% of world energy, and excess nitrogen pollutes rivers and coasts.',
    m(el, K) {
      const s = { T: 450, P: 200 }; const out = h('div');
      const draw = () => { const Kp = Math.exp(11000 / (s.T + 273) - 13.5); const yieldEq = Math.min(0.98, (Kp * s.P) / (1 + Kp * s.P) * 0.9); const rate = Math.exp(-8000 / (s.T + 273)) / Math.exp(-8000 / 723); const perHour = yieldEq * Math.min(1, rate * 0.35) * 100; const cost = 0.6 + s.P / 250 + (s.T - 300) / 600;
        out.innerHTML = `<div class="grid g4"><div><div class="tiny muted">Equilibrium yield</div><b>${(yieldEq * 100).toFixed(0)}%</b></div><div><div class="tiny muted">Reaction speed</div><b>${rate.toFixed(2)}×</b></div><div><div class="tiny muted">Ammonia per hour (relative)</div><b>${perHour.toFixed(1)}</b></div><div><div class="tiny muted">Running cost (relative)</div><b>${cost.toFixed(2)}</b></div></div><p class="small">Profit index: <b>${(perHour / cost).toFixed(1)}</b>. Try to beat the industrial compromise (≈450 °C, 200 atm).</p>`; };
      el.append(K.slider('Temperature (°C)', 200, 700, 5, s.T, (v) => { s.T = v; draw(); }), K.slider('Pressure (atm)', 10, 400, 5, s.P, (v) => { s.P = v; draw(); }), out, h('p', { class: 'tiny muted' }, 'A toy model with made-up constants tuned to show the real trade-offs, not real yields.')); draw();
    } });

  A({ id: 'battery', d: ['chemistry', 'physics', 'engineering'], e: '🔋', t: 'Build a battery from metals', b: 'Pick two metals and see the voltage. Why lithium makes such good batteries.',
    how: 'Each metal has a standard reduction potential: how strongly it holds electrons. Pair two in a cell and electrons flow from the one that gives them up more easily (anode) to the other (cathode). Cell voltage = E(cathode) − E(anode). Alessandro Volta stacked zinc and copper in 1800. Lithium has the most negative potential (−3.04 V) and is very light.',
    use: 'Phone and car batteries, corrosion prevention (zinc “sacrificial anodes” on ships), electroplating and fuel cells.',
    m(el, K) {
      const E = { Lithium: -3.04, Potassium: -2.93, Sodium: -2.71, Magnesium: -2.37, Aluminium: -1.66, Zinc: -0.76, Iron: -0.44, Nickel: -0.25, Lead: -0.13, Hydrogen: 0, Copper: 0.34, Silver: 0.8, Gold: 1.5 }; let a = 'Zinc', b = 'Copper'; const out = h('div'); const P = K.canvas(el, 140);
      const draw = () => { const [an, ca] = E[a] < E[b] ? [a, b] : [b, a]; const V = E[ca] - E[an]; P.clear(); const { X } = P.chart(-3.2, 1.6, 0, 1, { noY: true, xl: 'standard reduction potential (V)' }); Object.entries(E).forEach(([n, v], i) => { P.dot(X(v), 40 + (i % 3) * 18, n === a || n === b ? 7 : 4, n === an ? '#DC2626' : n === ca ? '#2563EB' : '#94A3B8'); if (n === a || n === b) P.text(n, X(v), 30 + (i % 3) * 18, { a: 'center', s: 11, w: 700 }); });
        out.innerHTML = `<div class="kpi">${V.toFixed(2)} V <small>${an} gives up electrons (anode, −) → ${ca} receives them (cathode, +)</small></div>`; };
      const sel = (v, on) => { const s = h('select', null, Object.keys(E).map((k) => h('option', { value: k, selected: k === v }, k))); s.onchange = () => on(s.value); return s; };
      P.onResize = draw; el.append(h('div', { class: 'row' }, sel(a, (v) => { a = v; draw(); }), h('span', null, '+'), sel(b, (v) => { b = v; draw(); })), out); draw();
    } });

  // ======================= LAW =======================
  A({ id: 'amend', d: ['law', 'politics', 'history'], e: '📜', t: 'Amend the Constitution', b: 'Two-thirds of Congress, then three-quarters of the states. Try to pass an amendment.',
    how: 'Article V requires two-thirds of both houses of Congress to propose an amendment and three-quarters of the states (38 of 50) to ratify. Over 11,000 amendments have been proposed; only 27 ratified, the last in 1992 (first proposed in 1789). The Equal Rights Amendment passed Congress in 1972 but stalled in the states.',
    use: 'Why the US constitution changes mainly through court interpretation, comparing with countries that amend more easily (India has amended its constitution over 100 times).',
    m(el, K) {
      let support = 60, polar = 0.5; const out = h('div');
      const run = () => { const house = Lab.clamp(support + K.gauss() * 4, 0, 100), senate = Lab.clamp(support + K.gauss() * 6, 0, 100); let states = 0; const st = []; for (let i = 0; i < 50; i++) { const lean = K.gauss() * 18 * polar * 2; const sup = support + lean + K.gauss() * 5; const yes = sup > 55; if (yes) states++; st.push(yes); } const passC = house >= 66.7 && senate >= 66.7;
        out.innerHTML = `<p>House: <b>${house.toFixed(0)}%</b> ${house >= 66.7 ? '✓' : '✗'} · Senate: <b>${senate.toFixed(0)}%</b> ${senate >= 66.7 ? '✓' : '✗'} (need 2/3)</p>` + (passC ? `<p>States ratifying: <b>${states}</b> of 50 (need 38) ${states >= 38 ? '🎉 <b>Ratified!</b>' : '✗ Fails in the states.'}</p><div style="display:grid;grid-template-columns:repeat(25,1fr);gap:3px">${st.map((y) => `<div style="height:16px;border-radius:3px;background:${y ? '#16A34A' : '#DC2626'}"></div>`).join('')}</div>` : '<p>Dies in Congress before reaching the states.</p>'); };
      el.append(K.slider('National public support (%)', 30, 95, 1, support, (v) => (support = v)), K.slider('How divided the states are', 0, 1, 0.05, polar, (v) => (polar = v)), K.btn('Propose the amendment', run, true), out, h('p', { class: 'tiny muted' }, 'Simplified: assumes legislators follow public support in their state.')); run();
    } });

  A({ id: 'scotus', d: ['law', 'politics'], e: '🏛️', t: 'The median justice', b: 'Place nine justices on a spectrum and decide cases. The swing vote often decides everything.',
    how: 'On a court that decides by majority, if justices line up on one dimension, the median (5th) justice decides the outcome. Political scientists measure positions with voting data (Martin–Quinn scores). Justices Kennedy (until 2018) and later Roberts or others were often the median. Real cases don’t always split on one dimension; many are unanimous (often around 40% of a term’s cases).',
    use: 'Predicting rulings, confirmation fights, and understanding why a single appointment can shift the law for decades.',
    m(el, K) {
      const P = K.canvas(el, 200); let J = [-2.5, -1.8, -1.2, 0.3, 0.6, 1.0, 1.6, 2.2, 3.0], kase = 0.2; const out = K.out();
      const draw = () => { P.clear(); const { X } = P.chart(-4, 4, 0, 1, { noY: true, xl: '← more liberal · more conservative →' }); P.line([[X(kase), 10], [X(kase), 150]], '#CA8A04', 3); P.text('case cutpoint', X(kase) + 4, 20, { c: '#CA8A04', s: 11 }); const s = [...J].sort((a, b) => a - b);
        s.forEach((x, i) => P.dot(X(x), 90, i === 4 ? 12 : 9, x > kase ? '#DC2626' : '#2563EB')); P.text('median', X(s[4]), 120, { a: 'center', s: 11, w: 700 }); const right = J.filter((x) => x > kase).length; out.innerHTML = `Ruling: <b>${right}–${9 - right}</b> for the ${right >= 5 ? 'conservative' : 'liberal'} side. The median justice (at ${s[4].toFixed(1)}) is on the winning side every time.`; };
      P.onResize = draw; el.append(K.slider('Where the case falls (the line between outcomes)', -3.5, 3.5, 0.05, kase, (v) => { kase = v; draw(); }), K.btn('Replace the median justice', () => { const s = [...J].sort((a, b) => a - b); const i = J.indexOf(s[4]); J[i] = K.rnd(-3, 3); draw(); }), out, h('p', { class: 'tiny muted' }, 'Positions are illustrative, not real justices’ scores.')); draw();
    } });

  A({ id: 'handformula', d: ['law', 'economics', 'ethics'], e: '🧮', t: 'Negligence: the Hand formula', b: 'Should a company have spent money to prevent an accident? Judge Learned Hand’s formula B < P × L.',
    how: 'In United States v. Carroll Towing (1947), Judge Learned Hand said a party is negligent if the burden of precaution (B) is less than the probability of harm (P) times the size of the loss (L). It frames negligence as cost-benefit; critics argue some harms (to life, dignity) shouldn’t be priced, and that it ignores who bears the risk.',
    use: 'Product safety, medical malpractice, workplace safety, self-driving car liability and corporate risk management.',
    m(el, K) {
      const s = { B: 50000, P: 1, L: 2000000 }; const out = h('div');
      const draw = () => { const PL = (s.P / 100) * s.L; out.innerHTML = `<div class="kpi" style="color:${s.B < PL ? '#DC2626' : '#16A34A'}">${s.B < PL ? 'Negligent' : 'Not negligent'} <small>B = $${Lab.fmt(s.B)} vs P × L = $${Lab.fmt(PL)}</small></div><p class="small">${s.B < PL ? 'The precaution was cheaper than the expected harm, so failing to take it was negligent under Hand’s test.' : 'The precaution costs more than the expected harm; under Hand’s test, skipping it was reasonable. Do you agree?'}</p>`; };
      el.append(K.slider('Burden: cost of the precaution ($)', 1000, 500000, 1000, s.B, (v) => { s.B = v; draw(); }), K.slider('Probability of the accident without it (%)', 0.1, 20, 0.1, s.P, (v) => { s.P = v; draw(); }), K.slider('Loss if it happens ($)', 10000, 10000000, 10000, s.L, (v) => { s.L = v; draw(); }), out,
        h('p', { class: 'tiny muted' }, 'Example: the 1970s Ford Pinto fuel-tank case is often cited (with disputed figures) in debates over cost-benefit reasoning about human lives.')); draw();
    } });

  A({ id: 'plea', d: ['law', 'ethics', 'statistics', 'psychology'], e: '🤝', t: 'The plea bargain dilemma', b: 'Take 2 years now, or risk 15 at trial? Even an innocent person might rationally plead guilty.',
    how: 'About 97–98% of US federal convictions come from guilty pleas rather than trials (US Sentencing Commission). Prosecutors offer lighter sentences for pleading; the gap between the offer and the possible trial sentence (the “trial penalty”) creates pressure. The National Registry of Exonerations has documented hundreds of innocent people who pleaded guilty.',
    use: 'Criminal justice reform debates, how courts manage caseloads, and decision-making under risk.',
    m(el, K) {
      const s = { offer: 2, trial: 15, p: 30 }; const out = h('div');
      const draw = () => { const ev = (s.p / 100) * s.trial; out.innerHTML = `<p>Expected sentence if you go to trial: ${s.p}% × ${s.trial} yrs = <b>${ev.toFixed(1)} years</b>. Plea offer: <b>${s.offer} years</b> (certain).</p><div class="kpi" style="color:${s.offer < ev ? '#DC2626' : '#16A34A'}">${s.offer < ev ? 'A risk-neutral person would plead' : 'Going to trial looks better on average'}</div><p class="small">Now imagine you are innocent but evidence looks bad (30% conviction risk) and the trial sentence is severe. Many people are risk-averse, so the pressure to plead is even stronger than the math suggests.</p>`; };
      el.append(K.slider('Plea offer (years)', 0, 15, 0.5, s.offer, (v) => { s.offer = v; draw(); }), K.slider('Sentence if convicted at trial (years)', 1, 40, 1, s.trial, (v) => { s.trial = v; draw(); }), K.slider('Chance of conviction at trial (%)', 1, 99, 1, s.p, (v) => { s.p = v; draw(); }), out); draw();
    } });

  A({ id: 'publicdomain', d: ['law', 'arts', 'literature', 'economics'], e: '©️', t: 'Is it in the public domain?', b: 'When does a book, song or film become free for anyone to use in the US? Calculate it.',
    how: 'US copyright originally lasted 14 years, renewable once (1790). Today: works published 1930–1977 get 95 years from publication; works from 1978 on last the author’s life plus 70 years (or 95 years for corporate works). As of January 1, 2026, US works published in 1930 or earlier are in the public domain. Some 1930–1963 works are already free because their copyright wasn’t renewed.',
    use: 'Using images, music and texts legally, remixing culture (Mickey Mouse’s 1928 Steamboat Willie entered the public domain in 2024), and the debate between creators’ incentives and public access.',
    m(el, K) {
      let mode = 'pub', year = 1950, death = 1990; const out = h('div'); const now = 2026;
      const draw = () => { let pd, note; if (mode === 'pub') { pd = year <= 1977 ? year + 96 : null; note = year <= 1977 ? `Published ${year} → public domain on January 1, ${pd}.` : 'Published 1978 or later: depends on the author’s death (switch mode).'; } else { pd = death + 71; note = `Author died ${death} → public domain on January 1, ${pd} (life + 70 years).`; }
        out.innerHTML = `<div class="kpi" style="color:${pd && pd <= now ? '#16A34A' : '#DC2626'}">${pd ? (pd <= now ? 'Public domain ✓' : 'Still under copyright') : '—'}</div><p class="small">${note}</p><p class="tiny muted">US rules only; other countries differ. General education, not legal advice.</p>`; };
      el.append(K.choice([['pub', 'Published before 1978'], ['life', 'Published 1978 or later']], mode, (v) => { mode = v; draw(); }), K.slider('Year first published', 1900, 1977, 1, year, (v) => { year = v; draw(); }), K.slider('Year the author died', 1950, 2025, 1, death, (v) => { death = v; draw(); }), out); draw();
    } });

  A({ id: 'proof', d: ['law', 'statistics', 'logic'], e: '📐', t: 'Standards of proof', b: 'Different decisions need different amounts of evidence. Match cases to the right standard.',
    how: 'Common-law systems use a ladder: reasonable suspicion (police stops), probable cause (arrests, warrants), preponderance of the evidence (most civil cases: more likely than not), clear and convincing evidence (e.g. terminating parental rights) and beyond a reasonable doubt (criminal convictions). Courts deliberately avoid assigning exact percentages.',
    use: 'Understanding why O. J. Simpson was acquitted in his criminal trial (1995) but found liable in the civil case (1997): same facts, different standard.',
    m(el, K) {
      K.quiz([['A jury decides whether to convict someone of robbery.', ['Preponderance', 'Beyond a reasonable doubt', 'Probable cause'], 1, 'Criminal convictions need the highest standard.'], ['A judge decides whether a car crash was the other driver’s fault in a lawsuit for damages.', ['Preponderance of the evidence', 'Beyond a reasonable doubt'], 0, 'Most civil cases: more likely than not.'], ['A police officer briefly stops someone acting suspiciously (a “Terry stop”).', ['Reasonable suspicion', 'Probable cause', 'Clear and convincing'], 0, 'Terry v. Ohio (1968).'], ['A judge issues a search warrant.', ['Probable cause', 'Beyond a reasonable doubt'], 0, 'The Fourth Amendment requires probable cause for warrants.'], ['A court permanently ends a parent’s rights to their child.', ['Preponderance', 'Clear and convincing evidence'], 1, 'Santosky v. Kramer (1982) required at least clear and convincing evidence.']], el);
    } });

  // ======================= RELIGION =======================
  A({ id: 'religionconcepts', d: ['religion', 'philosophy', 'linguistics'], e: '📿', t: 'Key ideas across traditions', b: 'Dharma, grace, tawhid, nirvana, the Tao, covenant. Match each concept to its tradition and meaning.',
    how: 'Each tradition has core concepts that don’t translate neatly. Understanding them in their own terms (an approach scholars call emic) avoids forcing one religion’s categories onto another.',
    use: 'Interfaith understanding, reading world literature and history, and travel or work across cultures.',
    m(el, K) {
      K.quiz([['Tawhid, the absolute oneness of God, is central to:', ['Islam', 'Hinduism', 'Shinto'], 0, 'The foundation of Islamic theology; associating partners with God (shirk) is the gravest sin.'], ['Nirvana, the extinguishing of craving and release from rebirth, is the goal in:', ['Judaism', 'Buddhism', 'Confucianism'], 1, 'Literally “blowing out” in Sanskrit.'], ['Grace, God’s unearned favor, especially in salvation, is emphasized in:', ['Christianity (especially Protestant theology)', 'Jainism', 'Taoism'], 0, 'Luther’s “sola gratia” was central to the Reformation; Catholic and Orthodox theology also stress grace.'],
        ['Covenant (brit), a binding relationship between God and a people, is central to:', ['Judaism', 'Buddhism', 'Shinto'], 0, 'From Abraham and Sinai; also inherited by Christianity.'], ['Dharma (duty, cosmic order, right way of living) is a key term in:', ['Hinduism, Buddhism, Jainism and Sikhism', 'Islam only', 'Zoroastrianism only'], 0, 'Its meaning varies across these traditions.'], ['The Tao (Dao), the way or underlying flow of the universe, comes from:', ['Taoism (and Chinese thought broadly)', 'Christianity', 'Sikhism'], 0, '“The Tao that can be told is not the eternal Tao” opens the Daodejing.'], ['Ahimsa, non-harm to all living beings, is most strictly practiced in:', ['Jainism', 'Norse religion', 'Aztec religion'], 0, 'Some Jain monks sweep the path to avoid stepping on insects; Gandhi drew on ahimsa.'], ['Seva (selfless service) and langar (free community kitchen) are central to:', ['Sikhism', 'Shinto', 'Mormonism'], 0, 'The Golden Temple in Amritsar serves free meals to around 100,000 people a day.']], el);
    } });

  A({ id: 'godarguments', d: ['religion', 'philosophy', 'logic'], e: '❓', t: 'Arguments about God', b: 'The cosmological, design, moral and ontological arguments, and the problem of evil. Rate each, then see the replies.',
    how: 'Philosophers of religion have debated these for millennia: Anselm (ontological, 1078), Aquinas (Five Ways, 1270s), al-Ghazali and the kalam cosmological argument, Paley’s watchmaker (1802), and the problem of evil from Epicurus to Hume (1779). Surveys of professional philosophers (PhilPapers, 2020) found about two-thirds lean toward atheism, while philosophers of religion mostly lean theist.',
    use: 'Thinking clearly about your own beliefs, understanding religious and secular worldviews, and practicing argument evaluation.',
    m(el, K) {
      cards(K, el, [['Cosmological (kalam)', 'Whatever begins to exist has a cause. The universe began to exist. So the universe has a cause, which defenders identify with God.', ['Convincing', 'Not convincing', 'Unsure'], 'Defenders: the Big Bang supports a beginning. Critics: causation may not apply to the universe as a whole; even if it has a cause, why a personal God?'],
        ['Design (fine-tuning)', 'Physical constants seem finely tuned for life; small changes would make life impossible. Best explanation: a designer.', ['Convincing', 'Not convincing', 'Unsure'], 'Defenders: the odds are astronomical. Critics: multiverse theories, the anthropic principle (we could only observe a life-permitting universe), and evolution explains biological design.'],
        ['Moral argument', 'If objective moral truths exist (torturing for fun is wrong), they need a foundation; God is the best one.', ['Convincing', 'Not convincing', 'Unsure'], 'Critics: Plato’s Euthyphro dilemma (is something good because God commands it, or does God command it because it is good?), and secular moral realism.'],
        ['Ontological (Anselm)', 'God is that than which nothing greater can be conceived. Existing in reality is greater than existing only in the mind. So God exists.', ['Convincing', 'Not convincing', 'Unsure'], 'Gaunilo’s perfect island parody and Kant’s “existence is not a predicate” are classic replies; modal versions (Plantinga) are still debated.'],
        ['Problem of evil', 'If an all-good, all-powerful God existed, there would be no pointless suffering. There is. So such a God doesn’t exist.', ['Convincing', 'Not convincing', 'Unsure'], 'Replies (theodicies): free will, soul-making (Hick), our limited view (skeptical theism). Critics point to natural suffering like childhood diseases.']]);
    } });

  A({ id: 'branches', d: ['religion', 'history'], e: '🌳', t: 'How traditions branched', b: 'Explore the major splits within Christianity, Islam, Buddhism and Judaism, with dates and causes.',
    how: 'Religions divide over authority, doctrine and politics. The Sunni–Shia split began with the succession after Muhammad (632). The Great Schism between Catholic and Orthodox churches is dated to 1054; the Protestant Reformation to 1517. Buddhism’s Theravada and Mahayana schools diverged over centuries after the Buddha.',
    use: 'Understanding conflicts (Northern Ireland, Iraq, Lebanon), politics, and the diversity within each tradition.',
    m(el, K) {
      const T = { Christianity: [['Early church', 30, 'Followers of Jesus in Judea, spreading through the Roman Empire'], ['Oriental Orthodox split', 451, 'Disagreement over Christ’s nature at the Council of Chalcedon (Coptic, Armenian, Ethiopian churches)'], ['Catholic–Orthodox Great Schism', 1054, 'Papal authority and theology; mutual excommunications'], ['Protestant Reformation', 1517, 'Luther’s 95 Theses; Lutheran, Reformed, Anglican and later Baptist, Methodist branches'], ['Pentecostalism', 1906, 'Azusa Street Revival in Los Angeles; now among the fastest-growing movements']], Islam: [['Prophet Muhammad’s death', 632, 'Dispute over succession'], ['Sunni', 632, 'Leadership by community choice: Abu Bakr; about 85–90% of Muslims today'], ['Shia', 661, 'Leadership through Ali and the Prophet’s family; split hardened after Karbala (680)'], ['Ibadi', 700, 'From early Kharijite movement; majority in Oman'], ['Sufism (mystical stream)', 800, 'Spans Sunni and Shia; emphasizes inner experience of God']], Buddhism: [['The Buddha’s teaching', -480, 'Northern India'], ['Early schools split', -300, 'Councils debate monastic rules and doctrine'], ['Theravada', -250, 'Spread to Sri Lanka, then Southeast Asia'], ['Mahayana', 100, 'Bodhisattva ideal; China, Korea, Japan, Vietnam (incl. Zen, Pure Land)'], ['Vajrayana', 700, 'Tantric practices; Tibet, Mongolia, Bhutan']], Judaism: [['Rabbinic Judaism', 70, 'After the Second Temple’s destruction, the Talmud becomes central'], ['Karaite', 800, 'Rejects rabbinic oral law'], ['Hasidism', 1740, 'Mystical revival in Eastern Europe (Baal Shem Tov)'], ['Reform', 1810, 'German modernizing movement'], ['Conservative & Modern Orthodox', 1850, 'Responses balancing tradition and modernity']] };
      let r = 'Christianity'; const P = K.canvas(el, 300);
      const draw = () => { P.clear(); const L = T[r]; const lo = Math.min(...L.map((x) => x[1])) - 50, hi = 2025; const { X } = P.chart(lo, hi, 0, 1, { noY: true, fx: (v) => (v < 0 ? -Math.round(v) + ' BC' : Math.round(v)) }); L.forEach(([n, y, d], i) => { const yy = 24 + i * 50; P.line([[X(y), yy], [X(hi), yy]], K.pal[i % 8], 6); if (i) P.line([[X(y), 24 + (i - 1) * 50], [X(y), yy]], K.pal[i % 8], 2, [3, 3]); P.text(`${n} (${y < 0 ? -y + ' BC' : y})`, X(y) + 4, yy - 8, { s: 11, w: 700 }); P.text(d.slice(0, 90), X(y) + 4, yy + 16, { s: 10, c: K.css('--muted') }); }); };
      P.onResize = draw; el.append(K.choice(Object.keys(T), r, (v) => { r = v; draw(); }), h('p', { class: 'tiny muted' }, 'Simplified; dates of gradual divergences are approximate and debated.')); draw();
    } });

  A({ id: 'churchstate', d: ['religion', 'politics', 'law', 'geopolitics'], e: '⛪', t: 'Religion and the state', b: 'Official religion, strict secularism, or something in between? Classify how countries handle religion.',
    how: 'Models range from theocracy (religious law and clergy rule, e.g. Iran), to an established church (the Church of England), to cooperation (Germany collects church tax), to separation (the US First Amendment), to strict secularism (France’s laïcité, 1905), to state atheism (the USSR, Albania 1967–90). Pew tracks government restrictions on religion, which rose globally over the 2010s.',
    use: 'Debates on religious symbols in schools, blasphemy laws, freedom of religion, and how states treat religious minorities.',
    m(el, K) {
      K.quiz([['Iran', ['Theocracy: clerics hold supreme authority', 'Strict secularism', 'Established church with free practice'], 0, 'The Supreme Leader is a senior cleric under the doctrine of velayat-e faqih.'], ['United Kingdom', ['Established church, with religious freedom for all', 'Theocracy', 'State atheism'], 0, 'The monarch heads the Church of England; 26 bishops sit in the House of Lords.'], ['France', ['Strict secularism (laïcité)', 'Established Catholic church'], 0, 'The 1905 law separated church and state; religious symbols are banned for public school pupils.'], ['United States', ['Separation: no establishment, free exercise', 'Established Protestant church'], 0, 'First Amendment (1791); the meaning of separation is debated in court cases to this day.'], ['Saudi Arabia', ['Islamic state; public practice of other religions restricted', 'Secular republic'], 0, 'The constitution is the Quran and Sunnah.'], ['India', ['Constitutionally secular, with religious personal laws', 'Hindu theocracy'], 0, 'Secular by constitution; debates over Hindu nationalism and the treatment of minorities are intense.'], ['China', ['Atheist party-state regulating five official religions', 'Buddhist state religion'], 0, 'Religious practice is permitted under state control; repression in Xinjiang and Tibet has drawn wide criticism.']], el);
    } });

  A({ id: 'pilgrimage', d: ['religion', 'anthropology', 'geopolitics'], e: '🛕', t: 'Pilgrimages of the world', b: 'Some of the largest human gatherings on Earth are pilgrimages. Match each to its tradition and place.',
    how: 'Pilgrimage, travel to a sacred place, appears in almost every tradition. Anthropologist Victor Turner described the “communitas” pilgrims feel when everyday social rank falls away. Some gatherings reach tens of millions of people, posing huge logistics and public-health challenges.',
    use: 'Tourism economies, crowd safety engineering, epidemiology (mass gatherings and disease), and diplomacy (Hajj quotas per country).',
    m(el, K) {
      K.quiz([['The Hajj, required once in a lifetime for Muslims who are able, goes to:', ['Mecca, Saudi Arabia', 'Jerusalem', 'Varanasi'], 0, 'About 1.8 million pilgrims in 2024 under a country quota system.'], ['The Kumbh Mela, possibly the largest gathering of humans, is a Hindu festival at:', ['Rivers in Prayagraj, Haridwar, Ujjain and Nashik', 'Mount Kailash only', 'Bodh Gaya'], 0, 'Organizers reported hundreds of millions of visits at Prayagraj in 2025.'], ['Arbaeen, one of the largest annual walks, takes Shia pilgrims to:', ['Karbala, Iraq', 'Mecca', 'Rome'], 0, 'It marks 40 days after the death of Imam Husayn in 680.'], ['The Camino de Santiago leads Christian pilgrims to:', ['Santiago de Compostela, Spain', 'Lourdes', 'Canterbury'], 0, 'Traditionally the shrine of the apostle James; walked by over 400,000 people a year recently.'], ['Bodh Gaya, India, is sacred because:', ['The Buddha attained enlightenment there', 'Muhammad was born there', 'Guru Nanak taught there'], 0, 'Under the Bodhi tree, around the 5th century BC.']], el);
    } });

  // ======================= LITERATURE =======================
  A({ id: 'haiku', d: ['literature', 'linguistics', 'arts'], e: '🍃', t: 'Write a haiku (or a sonnet line)', b: 'Write your own lines; the lab counts syllables per line and checks the form.',
    how: 'The Japanese haiku counts on (sound units) in a 5-7-5 pattern and traditionally includes a seasonal word (kigo). Matsuo Bashō (1644–1694) is its master. English adaptations count syllables, though many modern poets loosen it. Iambic pentameter lines have ten syllables.',
    use: 'Creative writing, compression and word choice, and understanding how form shapes meaning.',
    m(el, K) {
      let form = 'haiku'; const ta = h('textarea', { rows: 4, style: { width: '100%', fontSize: '16px' } }, 'An old silent pond\nA frog jumps into the pond\nSplash! Silence again'); const out = h('div');
      const syl = (w) => { w = w.toLowerCase().replace(/[^a-z]/g, ''); if (!w) return 0; if (w.length <= 3) return 1; w = w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '').replace(/^y/, ''); const m = w.match(/[aeiouy]{1,2}/g); return m ? m.length : 1; };
      const run = () => { const target = form === 'haiku' ? [5, 7, 5] : [10, 10, 10, 10]; const lines = ta.value.split('\n'); out.innerHTML = ''; lines.forEach((l, i) => { const n = (l.match(/[A-Za-z’']+/g) || []).reduce((a, w) => a + syl(w), 0); const t = target[i]; out.append(h('div', { class: 'row', style: { margin: '3px 0' } }, h('b', { style: { width: '40px', color: t === undefined ? null : n === t ? '#16A34A' : '#DC2626' } }, n), h('span', { class: 'small' }, l), t !== undefined ? h('span', { class: 'tiny muted' }, ` (target ${t})`) : null)); }); };
      ta.oninput = run; el.append(K.choice([['haiku', 'Haiku 5-7-5'], ['pent', 'Pentameter (10 per line)']], form, (v) => { form = v; run(); }), ta, out, h('p', { class: 'tiny muted' }, 'Syllables are estimated by a simple rule, so a few words may be off by one. The example is a common English rendering of Bashō’s frog haiku (1686).')); run();
    } });

  A({ id: 'translations', d: ['literature', 'linguistics', 'history'], e: '🌐', t: 'One line, many translations', b: 'The opening of Homer’s Odyssey across 300 years of English translators. Translation is interpretation.',
    how: 'Every translation chooses between literal accuracy, rhythm, rhyme and the culture of its readers. The Greek word polytropos (“of many turns”) in the first line has been rendered as wise, crafty, ingenious, complicated and more. Translators’ eras and beliefs shape their choices.',
    use: 'Reading world literature and scripture critically, diplomacy, law (treaties in several languages), and machine translation.',
    m(el, K) {
      const T = [['Greek original (8th century BC)', 'Ándra moi énnepe, Moûsa, polýtropon…', 'Word for word: “The man, to me tell, Muse, of many turns…”'], ['George Chapman (1616)', 'The man, O Muse, inform, that many a way / Wound with his wisdom to his wished stay;', 'Rhyming couplets; “many a way” for polytropos.'], ['Alexander Pope (1725)', 'The man for wisdom’s various arts renown’d, / Long exercised in woes, O Muse! resound;', 'Elegant 18th-century heroic couplets; polished and formal.'], ['Samuel Butler (1900)', 'Tell me, O muse, of that ingenious hero who travelled far and wide after he had sacked the famous town of Troy.', 'Plain prose; “ingenious” for polytropos.']];
      T.forEach(([w, l, n]) => el.append(h('div', { class: 'card', style: { boxShadow: 'none', marginBottom: '8px' } }, h('div', { class: 'tiny muted' }, w), h('p', { style: { fontSize: '16px', fontStyle: 'italic', margin: '4px 0' } }, l), h('div', { class: 'tiny' }, n))));
      el.append(h('p', { class: 'small' }, 'Modern translations (Fagles 1996, Wilson 2017) render polytropos as “man of twists and turns” and “a complicated man.” Emily Wilson was the first woman to publish an English translation of the Odyssey.'));
    } });

  A({ id: 'characternet', d: ['literature', 'sociology', 'computing'], e: '🕸️', t: 'Map a play’s social network', b: 'Romeo and Juliet as a network. Who connects the two feuding houses? Remove a character and see the play fall apart.',
    how: 'Digital humanities scholars map who speaks to whom. In Romeo and Juliet, a few “bridge” characters (Friar Laurence, the Nurse, Mercutio) connect the Montagues and Capulets. Network measures like betweenness centrality reveal who holds the plot together (Franco Moretti, 2011).',
    use: 'Literary analysis, studying real social networks, intelligence and fraud detection, and organizational design.',
    m(el, K) {
      const N = [['Romeo', 'M'], ['Montague', 'M'], ['Lady Montague', 'M'], ['Benvolio', 'M'], ['Mercutio', 'X'], ['Juliet', 'C'], ['Capulet', 'C'], ['Lady Capulet', 'C'], ['Tybalt', 'C'], ['Nurse', 'C'], ['Paris', 'X'], ['Friar Laurence', 'X'], ['Prince', 'X']];
      const E = [[0, 3], [0, 4], [0, 5], [0, 11], [0, 9], [0, 8], [0, 10], [1, 2], [1, 0], [1, 3], [1, 12], [3, 4], [3, 8], [4, 8], [5, 9], [5, 11], [5, 6], [5, 7], [5, 10], [6, 7], [6, 8], [6, 10], [6, 9], [7, 9], [8, 6], [11, 10], [12, 6], [12, 1], [12, 3], [10, 12]];
      const P = K.canvas(el, 380); let removed = new Set(); const out = K.out();
      const col = { M: '#2563EB', C: '#DC2626', X: '#64748B' };
      const draw = () => { P.clear(); const cx = P.W / 2, cy = P.H / 2, R = Math.min(cx, cy) - 40; const pos = N.map((_, i) => [cx + R * Math.cos((i / N.length) * 6.283 - 1.2), cy + R * Math.sin((i / N.length) * 6.283 - 1.2)]); const live = E.filter(([a, b]) => !removed.has(a) && !removed.has(b));
        live.forEach(([a, b]) => P.line([pos[a], pos[b]], '#94A3B888', 1.5)); N.forEach(([n, f], i) => { if (removed.has(i)) return; const deg = live.filter((e) => e.includes(i)).length; P.dot(...pos[i], 6 + deg * 1.5, col[f]); P.text(n, pos[i][0], pos[i][1] - 12 - deg, { a: 'center', s: 11, w: 600 }); });
        const adj = N.map(() => []); live.forEach(([a, b]) => { adj[a].push(b); adj[b].push(a); }); const seen = new Set([0]); const q = [0]; while (q.length) { const u = q.shift(); adj[u].forEach((v) => !seen.has(v) && (seen.add(v), q.push(v))); } const linked = seen.has(5);
        out.innerHTML = removed.has(0) || removed.has(5) ? 'Without a lover there is no story.' : linked ? 'Romeo and Juliet are still connected through the network.' : '<b>Romeo and Juliet are cut off from each other.</b>'; };
      P.c.onclick = (e) => { const [x, y] = P.pt(e); const cx = P.W / 2, cy = P.H / 2, R = Math.min(cx, cy) - 40; N.forEach((_, i) => { const px = cx + R * Math.cos((i / N.length) * 6.283 - 1.2), py = cy + R * Math.sin((i / N.length) * 6.283 - 1.2); if (Math.hypot(px - x, py - y) < 16) removed.has(i) ? removed.delete(i) : removed.add(i); }); draw(); };
      P.onResize = draw; el.append(h('p', { class: 'tiny muted' }, '🔵 Montagues · 🔴 Capulets · ⚪ others. Click a character to remove them (click again to restore). Try removing the Nurse and Friar Laurence.'), out, K.btn('Restore all', () => { removed = new Set(); draw(); })); draw();
    } });

  A({ id: 'archetypes', d: ['literature', 'psychology', 'anthropology', 'religion'], e: '🧙', t: 'Archetypes and the hero’s journey', b: 'Mentors, tricksters, shadows. Spot recurring character types across myths and novels.',
    how: 'Carl Jung proposed archetypes as universal patterns in the collective unconscious; Joseph Campbell (The Hero with a Thousand Faces, 1949) described the “monomyth” hero’s journey. Critics note the pattern is broad enough to fit almost anything and centers male heroes, but writers and screenwriters use it widely.',
    use: 'Storytelling and screenwriting (George Lucas credited Campbell), comparative mythology, marketing and brand stories.',
    m(el, K) {
      K.quiz([['Gandalf, Merlin, Athena guiding Odysseus (disguised as Mentor):', ['The mentor', 'The trickster', 'The shadow'], 0, 'The very word “mentor” comes from the Odyssey.'], ['Loki, Coyote, Anansi, Br’er Rabbit:', ['The trickster', 'The hero', 'The mother'], 0, 'Tricksters break rules and expose hypocrisy; found in Norse, Native American, West African and African American traditions.'], ['The hero refusing the call before setting out (Moses’ reluctance, Luke Skywalker initially):', ['A stage of the hero’s journey', 'An archetype of villainy'], 0, 'Campbell’s “refusal of the call”.'], ['The dark mirror of the hero, embodying what they could become (Darth Vader, Mr. Hyde):', ['The shadow', 'The herald'], 0, 'Jung’s shadow: the parts of ourselves we deny.']], el);
    } });

  // ======================= ETHICS =======================
  A({ id: 'discount', d: ['ethics', 'economics', 'earthspace', 'philosophy'], e: '⏳', t: 'How much do future people count?', b: 'The discount rate decides whether stopping climate damage in 100 years is worth paying for today.',
    how: 'Economists discount future costs: $1 later is worth less than $1 now. But discounting future people’s welfare is an ethical choice. The Stern Review (2006) used a low rate (about 1.4%), justifying strong climate action now; William Nordhaus (Nobel 2018) used about 4–5%, favoring a gradual policy ramp. Much of their disagreement came down to this one number.',
    use: 'Climate policy, infrastructure, pensions, nuclear waste, and any decision with long-run consequences.',
    m(el, K) {
      const s = { r: 1.4, yrs: 100, dmg: 1000 }; const out = h('div'); const P = K.canvas(el, 220);
      const draw = () => { const pv = s.dmg / (1 + s.r / 100) ** s.yrs; out.innerHTML = `<div class="kpi">$${Lab.fmt(pv, 1)} billion today <small>is the most it’s “worth” spending now to prevent $${Lab.fmt(s.dmg)} billion of damage in ${s.yrs} years at a ${s.r}% discount rate</small></div>`;
        P.clear(); const { X, Y } = P.chart(0, 7, 0, s.dmg, { xl: 'discount rate %', fy: (v) => '$' + Lab.fmt(v) + 'B' }); const pts = []; for (let r = 0; r <= 7; r += 0.05) pts.push([X(r), Y(s.dmg / (1 + r / 100) ** s.yrs)]); P.line(pts, '#16A34A', 3); P.dot(X(s.r), Y(pv), 7, '#DC2626'); [[1.4, 'Stern'], [4.5, 'Nordhaus']].forEach(([r, l]) => P.text(l, X(r), Y(s.dmg * 0.9), { a: 'center', s: 11, c: K.css('--muted') })); };
      P.onResize = draw; el.append(K.slider('Discount rate (% per year)', 0, 7, 0.1, s.r, (v) => { s.r = v; draw(); }), K.slider('Years until the damage', 10, 300, 5, s.yrs, (v) => { s.yrs = v; draw(); }), K.slider('Size of future damage ($ billions)', 100, 10000, 100, s.dmg, (v) => { s.dmg = v; draw(); }), out); draw();
    } });

  A({ id: 'consent', d: ['ethics', 'medicine', 'history', 'law'], e: '📝', t: 'Research ethics: cases that changed the rules', b: 'Tuskegee, Henrietta Lacks, Nazi experiments, Milgram. What went wrong and which rules came next?',
    how: 'Modern research ethics grew out of scandals. The Nuremberg Code (1947) followed Nazi medical crimes; the Declaration of Helsinki (1964) set international standards; the US Belmont Report (1979), prompted by the Tuskegee syphilis study, set three principles: respect for persons (informed consent), beneficence and justice.',
    use: 'Every clinical trial and university study today must pass ethics review; debates continue over data privacy, genetic samples and AI research on people.',
    m(el, K) {
      K.quiz([['From 1932 to 1972, the US Public Health Service observed Black men with syphilis in Alabama without treating them, even after penicillin became standard (1940s). The study is known as:', ['Tuskegee', 'Stanford prison', 'Willowbrook'], 0, 'It led to the Belmont Report and a 1997 presidential apology.'], ['In 1951, cells were taken from Henrietta Lacks’ tumor without her knowledge. They became the HeLa line used in polio vaccine and cancer research. The main ethical issue:', ['Lack of consent and benefit to her family', 'Bad science'], 0, 'Her family reached a settlement with a biotech company in 2023.'], ['The Nuremberg Code’s first principle (1947):', ['Voluntary consent is absolutely essential', 'Science comes first'], 0, 'Written in response to Nazi doctors’ experiments on prisoners.'], ['Milgram’s obedience studies (1961–62) deceived participants into thinking they were shocking others. Today such a study would likely:', ['Need strong justification, debriefing and ethics approval', 'Be standard practice'], 0, 'Modified replications (Burger, 2009) capped the fake shocks at 150 volts.']], el);
    } });

  A({ id: 'justwar', d: ['ethics', 'history', 'geopolitics', 'law', 'philosophy'], e: '🕊️', t: 'Just war theory', b: 'Apply the classic criteria for going to war to historical cases. Where do you and scholars disagree?',
    how: 'From Augustine and Aquinas to Michael Walzer (Just and Unjust Wars, 1977), just war theory asks whether a war is justified (just cause, legitimate authority, right intention, last resort, reasonable chance of success, proportionality) and whether it is fought justly (discrimination between combatants and civilians, proportionate force). The UN Charter (1945) allows force only in self-defense or with Security Council authorization.',
    use: 'Judging wars past and present, international law, military ethics training, and debates about humanitarian intervention.',
    m(el, K) {
      const C = ['Just cause', 'Legitimate authority', 'Last resort', 'Chance of success', 'Proportionality'];
      const W = [['Allied war against Nazi Germany (1939–45)', 'Most scholars judge the cause just; the bombing of German cities (Dresden, Hamburg) is widely debated as violating discrimination and proportionality.'], ['Iraq War (2003)', 'Contested: supporters cited weapons of mass destruction (none were found) and tyranny; critics cite no Security Council authorization, not last resort, and the war’s death toll.'], ['NATO in Kosovo (1999)', 'Humanitarian intervention without Security Council approval: many called it “illegal but legitimate” (Independent International Commission on Kosovo, 2000).'], ['Russian invasion of Ukraine (2022)', 'The UN General Assembly (141 states) demanded withdrawal; Russia cited NATO expansion and protection of Russian speakers, claims rejected by most international lawyers.'], ['Gulf War (1991)', 'Iraq’s invasion of Kuwait; authorized by Security Council Resolution 678; widely seen as meeting most criteria, though civilian infrastructure damage was criticized.']];
      W.forEach(([w, note]) => { const st = C.map(() => null); const fb = h('div', { class: 'small', style: { marginTop: '6px' } }); const row = h('div', { class: 'row' }); const redraw = () => { row.innerHTML = ''; C.forEach((c, i) => row.append(h('span', { class: 'chip' + (st[i] ? ' on' : ''), style: { '--c': st[i] === false ? '#DC2626' : '#16A34A' }, onclick: () => { st[i] = st[i] === null ? true : st[i] ? false : null; redraw(); } }, (st[i] === null ? '◻️ ' : st[i] ? '✅ ' : '❌ ') + c))); };
        redraw(); el.append(h('div', { class: 'card', style: { boxShadow: 'none', marginBottom: '10px' } }, h('b', null, w), h('p', { class: 'tiny muted' }, 'Click each criterion: met / not met / unsure'), row, K.btn('Compare with scholarly debate', () => (fb.textContent = note)), fb)); });
    } });

  A({ id: 'moralcircle', d: ['ethics', 'philosophy', 'biology', 'history'], e: '⭕', t: 'Who counts? The moral circle', b: 'Decide which beings deserve moral consideration, then see how the circle has widened (or not) through history.',
    how: 'Historian W. E. H. Lecky (1869) and philosopher Peter Singer (The Expanding Circle, 1981) describe moral concern spreading from family to tribe, nation, all humans, and for many now to animals and future generations. The expansion was neither steady nor universal: slavery, genocide and exclusion recur. Criteria proposed include sentience, rationality, relationships and species membership.',
    use: 'Animal welfare law, environmental ethics, AI rights debates, human rights and the treatment of future generations.',
    m(el, K) {
      const B = ['Family', 'Your community', 'People of your nation', 'All humans alive today', 'Future generations', 'Great apes', 'Dogs and pigs', 'Fish', 'Insects', 'Ecosystems and rivers', 'Advanced AI systems']; const on = new Set([0, 1, 2, 3]); const P = K.canvas(el, 320); const out = K.out(); const box = h('div', { class: 'row' });
      const draw = () => { box.innerHTML = ''; B.forEach((b, i) => box.append(h('span', { class: 'chip' + (on.has(i) ? ' on' : ''), style: { '--c': '#16A34A' }, onclick: () => { on.has(i) ? on.delete(i) : on.add(i); draw(); } }, b))); P.clear(); const cx = P.W / 2, cy = P.H / 2; B.forEach((b, i) => { const R = 18 + i * 13; P.ctx.strokeStyle = on.has(i) ? '#16A34A' : '#94A3B855'; P.ctx.lineWidth = on.has(i) ? 3 : 1; P.ctx.beginPath(); P.ctx.arc(cx, cy, R, 0, 7); P.ctx.stroke(); });
        out.innerHTML = 'Notable markers: Britain’s 1822 Martin’s Act (first animal cruelty law), the 1948 Universal Declaration of Human Rights, New Zealand granting legal personhood to the Whanganui River (2017). Ask yourself which criterion you used: feeling pain? reasoning? relationship to you?'; };
      P.onResize = draw; el.append(box, out); draw();
    } });

  A({ id: 'sweatshop', d: ['ethics', 'economics', 'geopolitics'], e: '🧵', t: 'The sweatshop debate', b: 'Low-wage factories: a ladder out of poverty or exploitation? Weigh the evidence on both sides.',
    how: 'Defenders (e.g. Paul Krugman’s 1997 essay, Benjamin Powell) argue factory jobs often pay more than local alternatives and helped Asian economies grow. Critics point to deadly conditions (Rana Plaza collapse, Bangladesh, 2013: 1,134 killed), suppressed unions and wage theft. A randomized study in Ethiopia (Blattman & Dercon, 2018) found factory jobs didn’t raise incomes over alternatives and had health risks.',
    use: 'Ethical shopping, trade agreements, corporate supply-chain standards and development policy.',
    m(el, K) {
      cards(K, el, [['A garment factory opens offering $3/day, versus $1.50/day in farm work. Conditions are hot and hours long. Good for workers?', 'Consider wages, alternatives, safety and freedom to organize.', ['Mostly good', 'Mostly bad', 'Depends on conditions'], 'Evidence is mixed: wages often beat local alternatives, but safety and rights vary enormously; outcomes depend heavily on enforcement and labor rights.'],
        ['Should Western consumers boycott brands that use such factories?', 'Boycotts can push reforms, or cost workers their jobs.', ['Boycott', 'Keep buying and push for standards', 'Unsure'], 'After Rana Plaza, the Bangladesh Accord (binding safety inspections) improved building safety; studies suggest targeted pressure plus inspections works better than blanket boycotts, though views differ.'],
        ['Should rich countries require minimum labor standards in trade deals?', 'Supporters: prevents a race to the bottom. Critics: disguised protectionism that hurts poor countries.', ['Yes', 'No', 'Unsure'], 'Many trade agreements (USMCA, EU deals) now include labor chapters; enforcement is debated.']]);
    } });

  // ======================= ANTHROPOLOGY =======================
  A({ id: 'kinship', d: ['anthropology', 'linguistics', 'sociology'], e: '👪', t: 'Kinship systems', b: 'In some languages your cousin is your “brother”. Switch kinship systems and watch the family tree relabel itself.',
    how: 'Lewis Henry Morgan (1871) classified how languages name relatives. Eskimo (like English) separates the nuclear family and lumps cousins. Hawaiian calls all cousins “brother/sister.” Iroquois calls parallel cousins (children of father’s brother or mother’s sister) siblings but cross cousins something else. Sudanese gives almost every relative a distinct term.',
    use: 'Understanding inheritance, marriage rules, obligations and family structure across cultures; translation; and fieldwork.',
    m(el, K) {
      const S = { Eskimo: { fb: 'uncle', ms: 'aunt', fbc: 'cousin', msc: 'cousin', fsc: 'cousin', mbc: 'cousin', sib: 'brother/sister' }, Hawaiian: { fb: 'father', ms: 'mother', fbc: 'brother/sister', msc: 'brother/sister', fsc: 'brother/sister', mbc: 'brother/sister', sib: 'brother/sister' }, Iroquois: { fb: 'father', ms: 'mother', fbc: 'brother/sister', msc: 'brother/sister', fsc: 'cross cousin', mbc: 'cross cousin', sib: 'brother/sister' }, Sudanese: { fb: 'father’s brother', ms: 'mother’s sister', fbc: 'father’s brother’s child', msc: 'mother’s sister’s child', fsc: 'father’s sister’s child', mbc: 'mother’s brother’s child', sib: 'brother/sister' } };
      let sys = 'Eskimo'; const box = h('div');
      const draw = () => { const t = S[sys]; const n = (l, w) => `<div style="padding:6px;border:1px solid var(--line);border-radius:8px;text-align:center;font-size:12px"><div class="muted" style="font-size:10px">${l}</div><b>${w}</b></div>`;
        box.innerHTML = `<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:8px">${n('Father’s brother', t.fb)}${n('Father', 'father')}${n('Mother', 'mother')}${n('Mother’s sister', t.ms)}${n('his child', t.fbc)}${n('Your sibling', t.sib)}<div style="padding:6px;border:2px solid #DB2777;border-radius:8px;text-align:center"><b>YOU</b></div>${n('her child', t.msc)}${n('Father’s sister’s child', t.fsc)}<div></div><div></div>${n('Mother’s brother’s child', t.mbc)}</div>`; };
      el.append(K.choice(Object.keys(S), sys, (v) => { sys = v; draw(); }), box, h('p', { class: 'tiny muted' }, 'Examples: Eskimo (English, most of Europe), Hawaiian (Hawaii, parts of Polynesia), Iroquois (Haudenosaunee, many others worldwide), Sudanese (parts of Sudan, Turkish, Chinese terms are highly descriptive).')); draw();
    } });

  A({ id: 'kula', d: ['anthropology', 'economics', 'sociology'], e: '🐚', t: 'The Kula ring: a gift economy', b: 'Shell necklaces travel clockwise, armbands counterclockwise around the islands. Nobody keeps them. Why?',
    how: 'Bronisław Malinowski (Argonauts of the Western Pacific, 1922) described the Kula of the Trobriand and surrounding islands in Papua New Guinea. Valuables circulate forever; prestige comes from giving and from the history of objects. Marcel Mauss (The Gift, 1925) argued gifts create obligations that bind societies together.',
    use: 'Understanding non-market economies, social obligations, reciprocity in your own life (gifts, favors, dinner invitations), and trust networks in business.',
    m(el, K) {
      const P = K.canvas(el, 360); const N = 10; let items = [], t = 0, run = true; const out = K.out(); const fame = Array(N).fill(0);
      items = Array.from({ length: 8 }, (_, i) => ({ k: i % 2 ? 'arm' : 'neck', at: K.ri(0, N - 1), p: 0 }));
      el.append(K.btn('⏯ Pause', () => (run = !run)), out);
      K.raf(() => { if (run) { t++; items.forEach((it) => { it.p += 0.006; if (it.p >= 1) { it.p = 0; fame[it.at] += 1; it.at = (it.at + (it.k === 'neck' ? 1 : N - 1)) % N; } }); }
        P.clear(); const cx = P.W / 2, cy = P.H / 2, R = Math.min(cx, cy) - 40; const pos = (i) => [cx + R * Math.cos((i / N) * 6.283 - 1.57), cy + R * Math.sin((i / N) * 6.283 - 1.57)];
        for (let i = 0; i < N; i++) { P.dot(...pos(i), 14 + Math.min(10, fame[i] / 3), '#16A34A'); P.text('🏝️', pos(i)[0] - 9, pos(i)[1] + 6, { s: 16 }); }
        items.forEach((it) => { const a = pos(it.at), b = pos((it.at + (it.k === 'neck' ? 1 : N - 1)) % N); const x = a[0] + (b[0] - a[0]) * it.p, y = a[1] + (b[1] - a[1]) * it.p; P.text(it.k === 'neck' ? '📿' : '💫', x - 8, y + 6, { s: 16 }); });
        out.textContent = '📿 necklaces (soulava) travel clockwise · 💫 armbands (mwali) counterclockwise · island size = prestige from giving'; });
    } });

  A({ id: 'domestication', d: ['anthropology', 'biology', 'history', 'earthspace'], e: '🐑', t: 'When we tamed plants and animals', b: 'Slide back through 15,000 years to see when and where dogs, wheat, rice, maize, horses and more were domesticated.',
    how: 'Farming began independently in at least about a dozen regions: the Fertile Crescent, China, Mesoamerica, the Andes, New Guinea, Africa’s Sahel and others. Genetics and archaeology keep revising dates. Jared Diamond’s Guns, Germs, and Steel (1997) argued the distribution of domesticable species shaped world history; critics say it underplays human choices and politics.',
    use: 'Food security and crop diversity, the origins of inequality and states, disease (many epidemics came from domestic animals), and conservation.',
    m(el, K) {
      const D = [[15000, 'Dog', 'Eurasia (wolves; possibly earlier)'], [11000, 'Sheep & goats', 'Fertile Crescent'], [10500, 'Wheat & barley', 'Fertile Crescent'], [10500, 'Cattle', 'Fertile Crescent & South Asia'], [9500, 'Cats (associated with humans)', 'Near East (burial on Cyprus)'], [9000, 'Rice', 'Yangtze valley, China'], [9000, 'Maize', 'Southern Mexico (from teosinte)'], [8000, 'Potato', 'Andes'], [7000, 'Squash, beans', 'Mesoamerica'], [6000, 'Llama & alpaca', 'Andes'], [5500, 'Horse (early)', 'Central Asia (Botai; modern lineage ~4,200 years ago)'], [4500, 'Sorghum', 'Sahel, Africa'], [3500, 'Chicken (as a food animal)', 'Southeast Asia']];
      let y = 15000; const box = h('div');
      const draw = () => { box.innerHTML = ''; D.forEach(([yr, n, wh]) => box.append(h('div', { class: 'row', style: { opacity: yr >= y ? 1 : 0.3, margin: '3px 0' } }, h('b', { class: 'small', style: { width: '110px' } }, `${Lab.fmt(yr)} yrs ago`), h('span', { class: 'small' }, `${n} — ${wh}`)))); };
      el.append(K.slider('Years ago', 3000, 15000, 100, y, (v) => { y = v; draw(); }), box, h('p', { class: 'tiny muted' }, 'Approximate earliest dates; many are actively revised by new genetic and archaeological evidence.')); draw();
    } });

  A({ id: 'relativism', d: ['anthropology', 'ethics', 'philosophy'], e: '🌏', t: 'Ethnocentrism vs cultural relativism', b: 'Real scenarios: is this practice strange, wrong, or just different? Where does relativism stop?',
    how: 'Franz Boas (early 1900s) argued cultures should be understood on their own terms, rejecting the ranking of “civilized” and “savage”. That method (methodological relativism) is now standard in anthropology. Moral relativism, the claim that no practice can be judged across cultures, is more controversial: most anthropologists and the 1948 Universal Declaration of Human Rights hold that some practices can be criticized.',
    use: 'Travel and international work, human rights debates, immigration and integration, and humility about your own culture’s habits.',
    m(el, K) {
      cards(K, el, [['Eating insects', 'About 2 billion people eat insects regularly; many Westerners find it disgusting.', ['Just different', 'Wrong'], 'A clear case of cultural difference; the UN FAO promotes insects as sustainable protein.'], ['Arranged marriage', 'Families choose or strongly guide spouses, with the couple’s consent.', ['Just different', 'Wrong', 'Depends on consent'], 'Most scholars distinguish arranged marriages (consent) from forced marriages (no consent), which international law prohibits.'], ['Tipping 15–20%', 'In the US, waiters depend on tips; in Japan tipping can be considered rude.', ['Just different', 'Wrong'], 'A norm that seems natural to Americans looks odd to many others.'], ['Female genital cutting', 'Practiced in parts of Africa, the Middle East and Asia, often defended as tradition.', ['Just different', 'Wrong', 'Unsure'], 'The WHO and UN classify it as a human rights violation; anthropologists study why it persists and how communities themselves have ended it (e.g. Tostan in Senegal).']]);
    } });

  // ======================= LINGUISTICS =======================
  A({ id: 'speakers', d: ['linguistics', 'geopolitics', 'history'], e: '🗣️', t: 'The world’s biggest languages', b: 'Native speakers vs total speakers. English is huge mainly as a second language; Mandarin as a first.',
    how: 'Ethnologue estimates about 7,000 living languages; the top 10 or so are spoken by about half of humanity. Languages spread through empire, trade, religion, migration and media. English’s second-language reach comes from British colonialism and American economic and cultural power.',
    use: 'Choosing languages to learn, business and diplomacy, education policy, and understanding linguistic inequality on the internet.',
    m(el, K) {
      const L = [['English', 380, 1500], ['Mandarin Chinese', 940, 1140], ['Hindi', 345, 610], ['Spanish', 485, 560], ['Arabic (standard, total)', 0, 300], ['French', 80, 310], ['Bengali', 235, 275], ['Portuguese', 235, 265], ['Russian', 150, 255], ['Urdu', 70, 235]]; let mode = 'total'; const box = h('div');
      const draw = () => { box.innerHTML = ''; box.append(bars([...L].sort((a, b) => (mode === 'total' ? b[2] - a[2] : b[1] - a[1])).map(([n, na, t], i) => [n, mode === 'total' ? t : na, K.pal[i % 8]]), 1600, (v) => (v ? v + 'M' : 'n/a'))); };
      el.append(K.choice([['total', 'Total speakers'], ['native', 'Native speakers']], mode, (v) => { mode = v; draw(); }), box, Lab.source('Rounded from Ethnologue (2023–24 editions). Arabic native speakers speak many regional varieties, so a single native figure isn’t shown.')); draw();
    } });

  A({ id: 'morphology', d: ['linguistics', 'literature'], e: '🧱', t: 'Build words from parts', b: 'Snap prefixes, roots and suffixes together. Discover how English builds “unbelievably” and “antidisestablishmentarianism”.',
    how: 'Morphemes are the smallest meaningful units. English mixes Germanic parts (un-, -ness) with Latin and Greek ones (re-, -tion, bio-). Languages differ hugely: Turkish and Finnish stack many suffixes on one word (agglutinative); Mandarin uses mostly separate words (isolating); Inuktitut can pack a whole sentence into one word (polysynthetic).',
    use: 'Vocabulary growth (knowing 30 roots unlocks thousands of words), spelling, reading science terms, and natural language processing.',
    m(el, K) {
      const pre = [['', ''], ['un', 'not'], ['re', 'again'], ['dis', 'opposite of'], ['pre', 'before'], ['anti', 'against'], ['over', 'too much']], root = [['believe', 'trust as true'], ['form', 'shape'], ['act', 'do'], ['establish', 'set up'], ['view', 'see'], ['port', 'carry']], suf = [['', ''], ['able', 'can be'], ['ment', 'act/result of'], ['ion', 'act/state'], ['er', 'one who'], ['ive', 'tending to'], ['ly', 'in a way']];
      let p = 1, r = 0, s = 1, s2 = 6; const out = h('div', { class: 'kpi', style: { margin: '10px 0' } }); const gl = h('div', { class: 'small' });
      const draw = () => { let w = pre[p][0] + root[r][0]; if (suf[s][0]) w = w.replace(/e$/, '') + suf[s][0]; if (suf[s2][0]) w = w.replace(/le$/, 'l') + (w.endsWith('l') && suf[s2][0] === 'ly' ? 'y' : suf[s2][0]); out.textContent = w; gl.innerHTML = [pre[p], root[r], suf[s], suf[s2]].filter((x) => x[0]).map((x) => `<b>${x[0]}</b> = ${x[1]}`).join(' + '); };
      el.append(h('div', { class: 'tiny muted' }, 'Prefix'), K.choice(pre.map((x, i) => [i, x[0] || '—']), p, (v) => { p = v; draw(); }), h('div', { class: 'tiny muted' }, 'Root'), K.choice(root.map((x, i) => [i, x[0]]), r, (v) => { r = v; draw(); }), h('div', { class: 'tiny muted' }, 'Suffix'), K.choice(suf.map((x, i) => [i, x[0] || '—']), s, (v) => { s = v; draw(); }), h('div', { class: 'tiny muted' }, 'Second suffix'), K.choice(suf.map((x, i) => [i, x[0] || '—']), s2, (v) => { s2 = v; draw(); }), out, gl, h('p', { class: 'tiny muted' }, 'Not every combination is a real word: morphology has rules and exceptions. Is “overportable” English? Why not?')); draw();
    } });

  A({ id: 'langdeath', d: ['linguistics', 'anthropology', 'sociology'], e: '🕯️', t: 'How languages die (and revive)', b: 'If parents stop passing a language to their kids, it can vanish in two generations. Model it, then try a revival.',
    how: 'Over 40% of the world’s roughly 7,000 languages are endangered (Ethnologue). The key factor is intergenerational transmission (Joshua Fishman’s scale, 1991). Hebrew was revived as a daily spoken language from the late 1800s; Welsh, Māori and Hawaiian have grown again through immersion schools.',
    use: 'Indigenous rights and cultural survival, education policy, and preserving knowledge encoded in languages (plant names, history, worldviews).',
    m(el, K) {
      const P = K.canvas(el, 260); const s = { trans: 50, school: 0 }; const out = K.out();
      const draw = () => { let sp = 5000; const pts = [[0, sp]]; for (let g = 1; g <= 8; g++) { sp = sp * (s.trans / 100) * 1.05 + (s.school / 100) * 2000; pts.push([g, sp]); } P.clear(); const mx = Math.max(6000, ...pts.map((p) => p[1])); const { X, Y } = P.chart(0, 8, 0, mx, { xl: 'generations (~25 years each)', yl: 'speakers' }); P.line(pts.map(([g, v]) => [X(g), Y(v)]), '#9333EA', 3);
        out.innerHTML = `After 8 generations (about 200 years): <b>${Lab.fmt(pts[8][1])}</b> speakers. ${pts[8][1] < 100 ? 'The language is effectively extinct.' : pts[8][1] > 5000 ? 'The language is growing.' : 'The language survives but is shrinking.'}`; };
      P.onResize = draw; el.append(K.slider('Share of children learning it at home (%)', 0, 100, 1, s.trans, (v) => { s.trans = v; draw(); }), K.slider('Immersion schools: new learners per generation (relative)', 0, 100, 1, s.school, (v) => { s.school = v; draw(); }), out); draw();
    } });

  // ======================= GEOPOLITICS =======================
  A({ id: 'nato', d: ['geopolitics', 'history', 'politics'], e: '🛡️', t: 'NATO’s growth, 1949–2024', b: 'Slide through 75 years of enlargement from 12 to 32 members. See the Cold War and post-Cold War waves.',
    how: 'NATO was founded in 1949 with 12 members; Article 5 says an attack on one is an attack on all (invoked once, after 9/11). Enlargement after 1990 is one of the most debated issues in geopolitics: supporters say countries chose to join for security; critics, including some realist scholars (John Mearsheimer), argue it provoked Russia. Finland (2023) and Sweden (2024) joined after Russia’s 2022 invasion of Ukraine.',
    use: 'Understanding European security, the war in Ukraine, US alliance commitments and defense spending debates (the 2% of GDP guideline, raised to a 5% target at the 2025 summit).',
    m(el, K) {
      const W = [[1949, 'Belgium, Canada, Denmark, France, Iceland, Italy, Luxembourg, Netherlands, Norway, Portugal, UK, US'], [1952, 'Greece, Turkey'], [1955, 'West Germany'], [1982, 'Spain'], [1990, 'East Germany (via reunification)'], [1999, 'Czech Republic, Hungary, Poland'], [2004, 'Bulgaria, Estonia, Latvia, Lithuania, Romania, Slovakia, Slovenia'], [2009, 'Albania, Croatia'], [2017, 'Montenegro'], [2020, 'North Macedonia'], [2023, 'Finland'], [2024, 'Sweden']];
      let y = 1949; const out = h('div'); const P = K.canvas(el, 200);
      const draw = () => { const n = W.filter((w) => w[0] <= y && w[0] !== 1990).reduce((a, w) => a + w[1].split(',').length, 0); P.clear(); const { X, Y } = P.chart(1949, 2025, 0, 35, { xl: 'year', yl: 'members', fx: (v) => Math.round(v) }); let c = 0; const pts = []; W.filter((w) => w[0] !== 1990).forEach((w) => { pts.push([X(w[0]), Y(c)]); c += w[1].split(',').length; pts.push([X(w[0]), Y(c)]); }); pts.push([X(2025), Y(c)]); P.line(pts, '#2563EB', 3); P.line([[X(y), Y(0)], [X(y), Y(35)]], '#DC2626', 1.5, [4, 4]); P.line([[X(1991), Y(0)], [X(1991), Y(35)]], K.css('--muted'), 1, [2, 2]); P.text('USSR dissolves', X(1991) + 3, Y(33), { s: 10, c: K.css('--muted') });
        out.innerHTML = `<div class="kpi">${y}: ${n} members</div>` + W.filter((w) => w[0] <= y).map((w) => `<div class="small"><b>${w[0]}</b> ${w[1]}</div>`).join(''); };
      P.onResize = draw; el.append(K.slider('Year', 1949, 2025, 1, y, (v) => { y = v; draw(); }), out); draw();
    } });

  A({ id: 'gdppower', d: ['geopolitics', 'economics'], e: '💹', t: 'Who is the biggest economy?', b: 'Measured at market exchange rates the US leads; adjusted for local prices (PPP), China does. Which matters for power?',
    how: 'Nominal GDP converts at market exchange rates; purchasing power parity (PPP) adjusts for how much things cost locally (a haircut is cheaper in Delhi than in New York). PPP better reflects domestic living standards and the volume of goods a country can produce; nominal better reflects buying power on world markets (oil, chips, weapons from abroad).',
    use: 'Comparing great powers, judging the US–China rivalry, development comparisons and investment decisions.',
    m(el, K) {
      const D = [['United States', 29.2, 29.2, 340], ['China', 18.7, 37.1, 1410], ['Germany', 4.7, 5.7, 84], ['Japan', 4.0, 6.6, 124], ['India', 3.9, 16.0, 1440], ['United Kingdom', 3.6, 4.0, 69], ['France', 3.2, 4.0, 68], ['Russia', 2.2, 6.9, 144], ['Brazil', 2.2, 4.7, 212]]; let mode = 'nom'; const box = h('div');
      const draw = () => { const v = (r) => (mode === 'nom' ? r[1] : mode === 'ppp' ? r[2] : (r[2] * 1e6) / r[3]); box.innerHTML = ''; box.append(bars([...D].sort((a, b) => v(b) - v(a)).map((r, i) => [r[0], v(r), K.pal[i % 8]]), mode === 'pc' ? 90000 : 40, (x) => (mode === 'pc' ? '$' + Lab.fmt(x / 1000, 0) + 'k' : '$' + x.toFixed(1) + 'T'))); };
      el.append(K.choice([['nom', 'Nominal GDP'], ['ppp', 'GDP at PPP'], ['pc', 'PPP per person']], mode, (v) => { mode = v; draw(); }), box, Lab.source('Approximate 2024 values rounded from IMF World Economic Outlook; population in millions (UN). Figures are revised often.')); draw();
    } });

  A({ id: 'thucydides', d: ['geopolitics', 'history', 'politics'], e: '⚔️', t: 'The Thucydides trap', b: 'When a rising power challenges a ruling one, does war follow? Explore Graham Allison’s 16 historical cases.',
    how: 'Thucydides wrote that the rise of Athens and the fear it caused in Sparta made war inevitable (431 BC). Graham Allison (Destined for War, 2017) studied 16 cases of rising vs ruling powers over 500 years: 12 ended in war. Critics argue the case selection is subjective, nuclear weapons change the logic, and some “peaceful” cases (US–UK) show war is avoidable.',
    use: 'The central debate about US–China relations, Taiwan, and how great powers can manage rivalry.',
    m(el, K) {
      const C = [['Portugal vs Spain (late 1400s)', 0], ['France vs Habsburgs (1500s)', 1], ['Habsburgs vs Ottomans (1500s)', 1], ['Habsburgs vs Sweden (1600s)', 1], ['Dutch Republic vs England (1600s)', 1], ['France vs Great Britain (late 1600s–1700s)', 1], ['UK vs France & Russia (1800s)', 1], ['France & Russia vs Germany (1870)', 1], ['China & Russia vs Japan (1890s–1900s)', 1], ['UK vs United States (early 1900s)', 0], ['UK & Russia vs Germany (1914)', 1], ['Soviet Union, France, UK vs Germany (1939)', 1], ['US vs Japan (1941)', 1], ['US vs Soviet Union (1940s–80s)', 0], ['UK & France vs Germany (1990s–now)', 0], ['US vs China (today)', null]];
      const box = h('div', { class: 'grid g2' }); C.forEach(([n, w]) => box.append(h('div', { class: 'small', style: { padding: '6px 10px', borderRadius: '8px', background: w === 1 ? '#DC262618' : w === 0 ? '#16A34A18' : '#CA8A0418' } }, (w === 1 ? '⚔️ War · ' : w === 0 ? '🕊️ No war · ' : '❓ Unresolved · ') + n)));
      el.append(box, h('p', { class: 'small' }, 'In the peaceful cases, what helped? Shared institutions, economic ties, accepting a changing balance, nuclear deterrence and skilled diplomacy are the usual answers.'), Lab.source('Belfer Center, Thucydides’s Trap Case File (Graham Allison).'));
    } });

  // ======================= LOGIC =======================
  A({ id: 'setops', d: ['logic', 'math', 'computing'], e: '🔵', t: 'Sets & Venn diagrams', b: 'Shade union, intersection, difference and complement. Build any combination of three sets.',
    how: 'Georg Cantor founded set theory in the 1870s; John Venn drew the diagrams in 1880. Union (A ∪ B) is anything in either; intersection (A ∩ B) in both; difference (A − B) in A but not B; complement (A′) everything outside A. These correspond exactly to OR, AND, AND NOT, NOT in logic and search engines.',
    use: 'Database queries (SQL joins), search filters, probability, and organizing any categories.',
    m(el, K) {
      const inp = h('input', { type: 'text', value: '(A & B) | C', style: { width: '220px', fontFamily: 'monospace' } }); const P = K.canvas(el, 300); const out = K.out();
      const draw = () => { const W = Math.floor(P.W), H = Math.floor(P.H); const c = [[W / 2 - 55, H / 2 - 35], [W / 2 + 55, H / 2 - 35], [W / 2, H / 2 + 50]], R = 90; let f; try { f = new Function('A', 'B', 'C', 'return !!(' + inp.value.replace(/[^ABC&|!~()\s-]/g, '').replace(/~/g, '!').replace(/(\w)\s*-\s*(\w|\()/g, '$1 && !$2') + ')'); f(0, 0, 0); out.textContent = ''; } catch (e) { out.textContent = 'Use A, B, C with & (and), | (or), ! (not), - (minus)'; return; }
        P.clear(); const st = 3; for (let y = 0; y < H; y += st) for (let x = 0; x < W; x += st) { const inn = c.map(([cx, cy]) => (x - cx) ** 2 + (y - cy) ** 2 < R * R); if (f(...inn)) P.rect(x, y, st, st, '#2563EB88'); } c.forEach(([cx, cy], i) => { P.ctx.strokeStyle = K.css('--ink'); P.ctx.lineWidth = 2; P.ctx.beginPath(); P.ctx.arc(cx, cy, R, 0, 7); P.ctx.stroke(); P.text('ABC'[i], cx + (i === 0 ? -50 : i === 1 ? 50 : 0), cy + (i === 2 ? 60 : -50), { a: 'center', s: 18, w: 800 }); }); };
      inp.oninput = draw; P.onResize = draw; el.append(h('div', { class: 'row' }, inp, ...[['A ∪ B', 'A | B'], ['A ∩ B', 'A & B'], ['A − B', 'A & !B'], ['Not A', '!A'], ['Only one', '(A & !B & !C) | (B & !A & !C) | (C & !A & !B)'], ['All three', 'A & B & C']].map(([l, f]) => K.btn(l, () => { inp.value = f; draw(); }))), out); draw();
    } });

  A({ id: 'hilbert', d: ['logic', 'math', 'philosophy'], e: '🏨', t: 'Hilbert’s infinite hotel', b: 'A hotel with infinitely many rooms, all full. Fit in one new guest, then infinitely many more.',
    how: 'David Hilbert (1924) used this to show infinite sets behave strangely: move every guest from room n to room n + 1 and room 1 is free. Move guest n to room 2n and all odd rooms empty out for a countably infinite bus. Cantor proved some infinities are bigger: the real numbers can’t be listed this way (diagonal argument, 1891).',
    use: 'Foundations of mathematics, computer science (what can and can’t be computed or enumerated), and philosophy of the infinite.',
    m(el, K) {
      let rooms = Array.from({ length: 24 }, (_, i) => 'G' + (i + 1)); const box = h('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(12,1fr)', gap: '4px', margin: '10px 0' } }); const out = K.out();
      const draw = () => { box.innerHTML = ''; rooms.forEach((g, i) => box.append(h('div', { style: { padding: '6px 2px', textAlign: 'center', borderRadius: '6px', fontSize: '11px', background: g ? (g.startsWith('N') ? '#16A34A' : g.startsWith('B') ? '#CA8A04' : '#2563EB') : 'var(--card2)', color: g ? '#fff' : 'inherit' } }, h('div', { style: { fontSize: '9px', opacity: 0.7 } }, '#' + (i + 1)), g || 'empty'))); box.append(h('div', { style: { gridColumn: 'span 12', textAlign: 'center' } }, '… and so on forever')); };
      el.append(h('div', { class: 'row' }, K.btn('1 new guest: everyone moves n → n+1', () => { rooms = ['N1', ...rooms.slice(0, 23)]; out.textContent = 'Room 1 is free and nobody lost a room. ∞ + 1 = ∞.'; draw(); }, true), K.btn('Infinite bus: everyone moves n → 2n', () => { const r = Array(24).fill(null); rooms.forEach((g, i) => { if (2 * (i + 1) <= 24) r[2 * (i + 1) - 1] = g; }); for (let i = 0; i < 24; i += 2) r[i] = 'B' + (i / 2 + 1); rooms = r; out.textContent = 'Old guests fill the even rooms; the bus passengers take all the odd rooms. ∞ + ∞ = ∞.'; draw(); }), K.btn('Reset', () => { rooms = Array.from({ length: 24 }, (_, i) => 'G' + (i + 1)); out.textContent = ''; draw(); })), box, out); draw();
    } });

  A({ id: 'boolsearch', d: ['logic', 'computing', 'history'], e: '🔎', t: 'Boolean search like a researcher', b: 'Filter a library of 40 documents with AND, OR, NOT and quotes. Find exactly what you need.',
    how: 'Search engines and library databases combine terms with Boolean logic. AND narrows, OR widens, NOT excludes. Librarians and researchers build precise queries this way, much faster than scrolling through results.',
    use: 'Academic databases, legal research (Westlaw, Lexis), job searches, email filters and finding sources for this Lab’s research notebook.',
    m(el, K) {
      const T = ['war', 'treaty', 'famine', 'revolution', 'trade', 'empire', 'religion', 'science', 'slavery', 'election']; const R = ['Europe', 'Asia', 'Africa', 'Americas']; const docs = Array.from({ length: 40 }, (_, i) => { const tags = Lab.shuffle(T).slice(0, 3); const r = R[i % 4]; const y = 1700 + K.ri(0, 32) * 10; return { t: `${r} ${y}s: ${tags.join(', ')}`, tags: [...tags, r.toLowerCase()], y }; });
      const inp = h('input', { type: 'text', value: 'war AND treaty NOT europe', style: { width: '100%', fontFamily: 'monospace' } }); const res = h('div', { class: 'small' });
      const run = () => { const q = inp.value.toLowerCase(); const toks = q.match(/\(|\)|and|or|not|[a-z]+/g) || []; let i = 0; const atom = (d) => { const t = toks[i++]; if (t === '(') { const v = or(d); i++; return v; } if (t === 'not') return !atom(d); return d.tags.includes(t); }; const and = (d) => { let v = atom(d); while (toks[i] && toks[i] !== 'or' && toks[i] !== ')') { if (toks[i] === 'and') i++; v = atom(d) && v; } return v; }; const or = (d) => { let v = and(d); while (toks[i] === 'or') { i++; v = and(d) || v; } return v; };
        const hits = docs.filter((d) => { i = 0; try { return or(d); } catch (e) { return false; } }); res.innerHTML = `<b>${hits.length}</b> of 40 documents match.<br>` + hits.map((d) => '• ' + d.t).join('<br>'); };
      inp.oninput = run; el.append(inp, h('div', { class: 'row', style: { marginTop: '6px' } }, ['war AND treaty NOT europe', 'famine OR slavery', '(revolution OR election) AND americas', 'science AND NOT religion', 'empire AND (asia OR africa)'].map((q) => K.btn(q, () => { inp.value = q; run(); }))), h('p', { class: 'tiny muted' }, 'Terms: ' + T.join(', ') + ', and regions europe, asia, africa, americas.'), res); run();
    } });

  // ======================= SOCIOLOGY =======================
  A({ id: 'matthew', d: ['sociology', 'economics', 'arts', 'statistics'], e: '🎧', t: 'The rich get richer (Matthew effect)', b: 'Fifty equally good songs. Let listeners see download counts and watch luck snowball into hits.',
    how: 'Robert Merton (1968) named the Matthew effect: famous scientists get more credit for the same work. Salganik, Dodds and Watts’ MusicLab experiment (2006) showed thousands of people songs; when they could see others’ downloads, success became more unequal and less predictable: the same song could be a hit in one “world” and a flop in another.',
    use: 'Why bestseller lists and viral hits are partly luck, career advantage, citation counts, wealth inequality and platform design.',
    m(el, K) {
      const P = K.canvas(el, 280); const N = 50; let social = 0.8, worlds; const out = K.out();
      const run = () => { const quality = Array.from({ length: N }, () => 1); worlds = [0, 1].map(() => { const d = Array(N).fill(0); for (let t = 0; t < 3000; t++) { const w = d.map((x, i) => quality[i] * (1 - social + social * (x + 1))); const tot = w.reduce((a, b) => a + b, 0); let r = Math.random() * tot, i = 0; while (r > w[i]) { r -= w[i]; i++; } d[i]++; } return d; });
        P.clear(); const mx = Math.max(...worlds.flat()); const bw = P.W / N; worlds.forEach((d, k) => d.forEach((v, i) => P.rect(i * bw + (k ? bw / 2 : 0), P.H - 10 - (v / mx) * (P.H - 30), bw / 2 - 1, (v / mx) * (P.H - 30), k ? '#DC2626' : '#2563EB')));
        const top = (d) => d.indexOf(Math.max(...d)) + 1; const share = (d) => (Math.max(...d) / 3000) * 100; out.innerHTML = `All 50 songs are equally good. World A’s hit: song #${top(worlds[0])} (${share(worlds[0]).toFixed(1)}% of downloads) · World B’s hit: song #${top(worlds[1])} (${share(worlds[1]).toFixed(1)}%).`; };
      P.onResize = run; el.append(K.slider('How much listeners follow the crowd', 0, 1, 0.05, social, (v) => { social = v; run(); }), K.btn('Rerun both worlds', run, true), out, h('p', { class: 'tiny muted' }, '🔵 World A · 🔴 World B. Same songs, same rules, different luck.')); run();
    } });

  A({ id: 'urban', d: ['sociology', 'geopolitics', 'economics', 'earthspace'], e: '🏙️', t: 'The urban century', b: 'In 1950 about 30% of people lived in cities; around 2007 it passed 50%. Explore the shift and the megacities.',
    how: 'The UN’s World Urbanization Prospects (2018) estimated the urban share at 30% in 1950, 55% in 2018, and projected 68% by 2050, with most growth in Asia and Africa. Sociologists from Georg Simmel (1903) to the Chicago School studied how cities change social life: more anonymity, more specialization, more opportunity.',
    use: 'Housing and transport planning, climate (cities produce most emissions but are more efficient per person), public health and politics (urban–rural divides).',
    m(el, K) {
      const D = [[1950, 30], [1960, 34], [1970, 37], [1980, 39], [1990, 43], [2000, 47], [2010, 52], [2018, 55], [2030, 60], [2040, 64], [2050, 68]]; let y = 2018; const P = K.canvas(el, 240); const out = K.out();
      const draw = () => { P.clear(); const { X, Y } = P.chart(1950, 2050, 0, 100, { xl: 'year', fy: (v) => v + '%', fx: (v) => Math.round(v) }); P.line(D.map(([a, b]) => [X(a), Y(b)]), '#2563EB', 3); P.line([[X(2018), Y(0)], [X(2018), Y(100)]], K.css('--muted'), 1, [3, 3]); P.text('projection →', X(2019), Y(95), { s: 10, c: K.css('--muted') }); P.line([[X(1950), Y(50)], [X(2050), Y(50)]], '#DC2626', 1, [5, 4]);
        const v = D.reduce((a, b) => (Math.abs(b[0] - y) < Math.abs(a[0] - y) ? b : a)); P.dot(X(v[0]), Y(v[1]), 7, '#DC2626'); out.innerHTML = `${v[0]}: <b>${v[1]}%</b> of the world lives in urban areas.`; };
      P.onResize = draw; el.append(K.slider('Year', 1950, 2050, 1, y, (v) => { y = v; draw(); }), out, bars([['Tokyo', 37.4], ['Delhi', 28.5], ['Shanghai', 25.6], ['São Paulo', 21.7], ['Mexico City', 21.6], ['Cairo', 20.1], ['Mumbai', 20.0]], 40, (v) => v + 'M'), Lab.source('UN DESA, World Urbanization Prospects 2018 (urban agglomerations, 2018). Newer UN estimates using a different city definition rank Jakarta and Dhaka higher.')); draw();
    } });

  A({ id: 'bystander', d: ['sociology', 'psychology', 'ethics'], e: '🚨', t: 'The bystander effect', b: 'Someone needs help. Does adding more witnesses make help more or less likely to come?',
    how: 'Darley and Latané (1968) staged a seizure over an intercom: 85% of participants who thought they were alone helped quickly, but only 31% of those who thought four others could hear. Responsibility gets diffused. The famous 1964 Kitty Genovese story (38 silent witnesses) was later shown to be exaggerated, and a 2019 study of real CCTV footage found someone intervened in 9 of 10 public conflicts.',
    use: 'First aid training (point at one person: “You, call 911”), workplace safety and reporting misconduct, online harassment.',
    m(el, K) {
      const P = K.canvas(el, 240); let pi = 0.4; const out = K.out();
      const draw = () => { P.clear(); const { X, Y } = P.chart(1, 20, 0, 1, { xl: 'number of bystanders', fy: (v) => Math.round(v * 100) + '%' }); const each = (n) => pi / Math.pow(n, 0.9); const any = (n) => 1 - (1 - each(n)) ** n; const p1 = [], p2 = []; for (let n = 1; n <= 20; n++) { p1.push([X(n), Y(each(n))]); p2.push([X(n), Y(any(n))]); } P.line(p1, '#DC2626', 3); P.line(p2, '#16A34A', 3);
        out.innerHTML = '<span style="color:#DC2626">Chance any one person helps</span> falls as the crowd grows; <span style="color:#16A34A">chance at least someone helps</span> can stay high. Both lab and real-world studies matter: in labs, diffusion is strong; in real public conflicts, someone usually steps in.'; };
      P.onResize = draw; el.append(K.slider('How likely a lone witness is to help', 0.1, 0.95, 0.01, pi, (v) => { pi = v; draw(); }), out); draw();
    } });
})();
